Consider the following C program segment:

```c
int fun(int n, int *fp) {
    int t, f;
    if (n <= 1) { *fp = 1; return 1; }
    t = fun(n-1, fp);
    f = t + *fp;
    *fp = t;
    return f;
}
int main() {
    int x = 0;
    printf("%d\n", fun(6, &x));
    return 0;
}
```
What is the output?

Consider the following C code:

```c
#include <stdio.h>
int f(int n) {
    static int x = 0;
    if (n <= 0) return 1;
    x = n + f(n-2);
    return x;
}
int main() {
    printf("%d\n", f(5));
    return 0;
}
```
What is the output?
